      if (current.length > 0) {
        current += ch;
      }
    } else {
      if (current.length > 0) {
        if (current !== 'a' && current !== 'the') {
          tokens.push(current);
        }
        current = '';
      }
    }
  }
  if (current.length > 0) {
    if (current !== 'a' && current !== 'the') {
      tokens.push(current);
    }
  }
  return tokens;
}

function normalize(text) {
  var s = String(text);
  s = s.normalize('NFKC');
  s = s.normalize('NFD');
  var result = '';
  var i, code;
  for (i = 0; i < s.length; i++) {
    code = s.charCodeAt(i);
    if (code >= 0x0300 && code <= 0x036F) {
      continue;
    }
    result += s[i];
  }
  result = result.toLowerCase();
  result = result.replace(/\s+/g, ' ');
  result = result.trim();
  return result;
}

function analyze(text) {
  var tokens = tokenize(text);
  var count = tokens.length;
  var unique = [];
  var frequencies = {};
  var seen = {};
  var i, token;
  for (i = 0; i < tokens.length; i++) {
    token = tokens[i];
    if (frequencies[token] === undefined) {
      frequencies[token] = 0;
    }
    frequencies[token] += 1;
    if (!seen[token]) {
      seen[token] = true;
      unique.push(token);
    }
  }
  var summary = count + ' tokens; ' + unique.length + ' unique';
  return { tokens: tokens, count: count, unique: unique, frequencies: frequencies, summary: summary };
}
